-- Every agent is a scenario. Module 1 has one scenario per team version holding a brief per
-- agent: the observations the facilitator sees once they pick that agent, and the role-play
-- brief the certifier uses. Facilitators choose freely; nothing needs assigning.

insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'team-coaching', 'A', 'Team 7 coaching (voice) · every agent is a scenario', false, '{"agents": {"Jordan": {"archetype": "New joiner below bridge targets", "public": {"headline": "Jordan is not yet meeting the bridge targets for new hires.", "observations": ["Jordan has been on the production floor for 6 weeks (joined W1).", "Jordan is polite and patient with customers; two customers thanked Jordan by name in surveys this month.", "Jordan''s AHT was 505 s in W6 against a bridge target of 480 s. QA is 83% (bridge target 80%).", "In the last four calls you monitored:", "a) In 2 of 4 calls, Jordan put the customer on hold for more than two minutes while searching the knowledge base (KB).", "b) In 2 of 4 calls, the new verification step timed out and Jordan restarted it from the beginning.", "c) In 1 call, Jordan skipped the closing summary; the customer came back the same day with the same question."]}, "hidden": "Jordan was never shown the KB quick-reference during nesting and searches the full KB instead. Tenured agents have a workaround when the new verification step timed out; nobody showed Jordan. Jordan thinks this session means they are about to be let go.", "unlock": "An open question about what happens during the holds, or what feels hardest right now.", "twists": [{"minute": 8, "line": "“Kim and Omar are just as slow. Why am I the only one here?”", "tests": "Explains the purpose of the session with data, without comparing agents"}, {"minute": 14, "line": "“Honestly, I thought you called me in to let me go.”", "tests": "Builds trust and reframes the session as support"}], "good": ["Builds rapport first: Jordan is new and nervous.", "Recognises what is working (soft skills, QA above bridge) before the gaps.", "Separates the team-wide rise since W4 from Jordan''s own gaps (long KB holds, restarts).", "Agrees the root causes with Jordan rather than announcing them.", "Plans to Jordan''s learning style: shadowing Ravi, a demo of the KB quick-reference.", "SMART plan with a follow-up date."], "red_flags": ["Tells Jordan the solution in the first 5 minutes", "Treats the team-wide rise as Jordan''s fault", "Ends without an agreed action or follow-up"]}, "Maya": {"archetype": "Tenured top performer slipping on CSAT and QA", "public": {"headline": "Maya has missed CSAT and QA targets for the last two weeks.", "observations": ["Maya has been on the program for 2 years and was the team''s top performer until W3.", "Maya''s CSAT fell from 4.7 in W3 to 4.1 in W6. The last two QA evaluations were 81% and 80% (target 82%).", "Maya missed 2 of the last 3 huddles and keeps the camera off in team meetings.", "In the last four calls you monitored:", "a) In 3 of 4 calls, Maya closed without asking if there was anything else or offering the retention offer.", "b) In 2 of 4 calls, Maya talked over the customer while they explained the problem.", "c) Maya still has the best AHT on the team (470 s)."]}, "hidden": "Maya applied for the SME role in W3. Ravi got it and nobody explained the decision. Maya feels unrecognised and has started looking at other jobs, and will only open up if they feel listened to.", "unlock": "An open question about how work feels lately, or what has changed since W3.", "twists": [{"minute": 8, "line": "“My numbers are still better than most of the team.”", "tests": "Acknowledges strengths and stays on the gap without arguing"}, {"minute": 14, "line": "“I applied for the SME role, you know. Nobody even told me why I didn''t get it.”", "tests": "Responds with empathy and addresses the career question alongside performance"}], "good": ["Opens with genuine rapport and recognition of the track record.", "Uses open and probing questions; lets Maya make the link between W3 and the drop.", "Treats the career disappointment as a root cause to address, not an excuse.", "Agrees a Start / Stop / Continue and a follow-up on the SME decision, with dates."], "red_flags": ["Lectures Maya on expectations without asking", "Ignores the career disappointment when it surfaces", "Speculates about Maya''s private life"]}, "Ben": {"archetype": "Tenured agent not following process or using the KB", "public": {"headline": "Ben received a QA red flag this week for not completing the new verification step.", "observations": ["Ben has been on the program for 4 years and new hires often go to Ben for help.", "QA red-flagged 2 of Ben''s calls in W6: the new verification step was not completed (a security question skipped).", "Ben has not opened the KB or the team channel since W4 (team average: 18 KB views a week).", "Two customers came back after Ben handled their requests with the old process.", "Ben''s AHT (492 s) and CSAT (4.4) are in line with the team."]}, "hidden": "Ben was on leave in W4 and missed the briefing on the new verification step. Ben believes the KB is out of date, so stopped checking it, and will get defensive if lectured.", "unlock": "A question about how they found out about the new verification step, or what they do when unsure of a process.", "twists": [{"minute": 8, "line": "“I''ve done this job for four years. I don''t need the KB.”", "tests": "Respects the experience while keeping the compliance risk on the table"}, {"minute": 14, "line": "“Wait, they changed it in W4? I was on leave that week.”", "tests": "Integrates new information: shifts from attitude to a missed update"}], "good": ["Acknowledges Ben''s experience and value to new hires.", "Explains the impact of the missed step (security, compliance, repeat contacts) factually.", "Discovers the missed W4 briefing through questions rather than assuming attitude.", "Action plan fits Ben''s style: a mock call on the new step, a KB check for process changes, maybe helping brief others.", "SMART follow-up: e.g. next 10 calls fully compliant, QA re-check next week."], "red_flags": ["Threatens disciplinary action before exploring the cause", "Just tells Ben to read the KB", "Leaves the compliance risk unaddressed"]}, "Leo": {"archetype": "Attendance pattern after a shift change", "public": {"headline": "Leo accounts for 5 of the team''s 13 Monday absences since W2.", "observations": ["Leo has been on the team for 1.5 years; call quality is solid (QA 88%).", "Leo was absent on 5 Mondays since W2 and logged in late on two more. Attendance is 88% (team 96%).", "Leo works the Sunday late shift (now ending at 01:00), which changed in W2.", "Leo has not raised any concern with you."]}, "hidden": "Since the Sunday late shift (now ending at 01:00) changed in W2, there is no bus that works for Leo; it leaves Leo exhausted or late on Mondays. Leo is embarrassed to mention it.", "unlock": "A question about what changed around W2, or how they get to and from work on that shift.", "twists": [{"minute": 8, "line": "“I''m here every other day, aren''t I?”", "tests": "Stays factual about the pattern without accusing"}, {"minute": 14, "line": "“Since the shift moved, there''s no bus that gets me there and back.”", "tests": "Integrates new information and looks for a practical solution"}], "good": ["Opens with rapport and recognises Leo''s call quality.", "Presents the attendance pattern neutrally and asks before assuming.", "Links the pattern to the W2 shift change through Leo''s own account.", "Agrees a practical plan (shift swap, transport option, escalate to workforce management) with a follow-up date."], "red_flags": ["Opens with a warning", "Ignores the transport issue once raised", "No follow-up agreed"]}, "Nina": {"archetype": "Attendance pattern with a personal cause", "public": {"headline": "Nina has missed 4 Mondays since W2.", "observations": ["Nina has been on the team for a year and is well liked; QA 87%, CSAT 4.4.", "Nina was absent on 4 Mondays since W2. Attendance is 89% (team 96%).", "Nina has always been reliable until W2."]}, "hidden": "Nina shared a car with a neighbour for the Sunday late shift (now ending at 01:00). When the shift changed in W2 the neighbour stopped working it, so Nina has no safe way to travel. Nina is worried about asking for special treatment.", "unlock": "A question about how they get to and from work, or what changed for them in W2.", "twists": [{"minute": 8, "line": "“Everyone has the odd day off. Why single me out?”", "tests": "Explains the pattern factually and with care"}, {"minute": 14, "line": "“My lift stopped when the shift changed. I didn''t want to make a fuss.”", "tests": "Responds with empathy and moves to a practical option"}], "good": ["Builds rapport and recognises Nina''s reliability before W2.", "Uses the data neutrally and asks open questions.", "Agrees a practical option and a follow-up."], "red_flags": ["Threatens escalation", "Ignores the reason once given"]}, "Kim": {"archetype": "New joiner with good quality but long handling", "public": {"headline": "Kim is above the bridge target on AHT.", "observations": ["Kim joined in W1 after working in retail; confident with customers.", "Kim''s AHT was 500 s in W6 (bridge target 480 s); QA 85% is above the bridge target.", "In 2 of 3 monitored calls, Kim spent several minutes on small talk before identifying the customer''s need.", "Kim offered a goodwill credit in one call without checking eligibility."]}, "hidden": "Kim believes long friendly chats are what great service looks like, from retail. Nobody has explained the call flow targets or the credit policy clearly.", "unlock": "A question about what great service means to them, or how they decide when to offer a credit.", "twists": [{"minute": 8, "line": "“Customers love chatting with me. Isn''t that the point?”", "tests": "Values the strength while linking it to the targets"}, {"minute": 14, "line": "“Nobody told me there were rules on credits.”", "tests": "Takes the new information as a knowledge gap, not misconduct"}], "good": ["Recognises the rapport strength.", "Helps Kim find a balance between warmth and efficiency.", "Clarifies the credit policy and agrees a measurable step with follow-up."], "red_flags": ["Tells Kim to stop chatting with customers", "Treats the credit as misconduct"]}, "Omar": {"archetype": "New joiner, quick with systems, light on empathy", "public": {"headline": "Omar is close to the bridge targets but customers rate the calls as cold.", "observations": ["Omar joined in W1 and studies IT part-time; quick with the systems.", "Omar''s AHT was 504 s in W6 (bridge target 480 s); QA 84%.", "In 2 of 3 monitored calls, Omar went straight to the fix without acknowledging the customer''s frustration.", "One survey comment: “Solved it, but felt like talking to a robot.”"]}, "hidden": "Omar thinks empathy statements waste the customer''s time and finds the scripted phrases fake.", "unlock": "A question about how they think the customer felt on a call, or what they think of the empathy phrases.", "twists": [{"minute": 8, "line": "“I fixed their problem. Isn''t that what matters?”", "tests": "Links empathy to CSAT and resolution without lecturing"}, {"minute": 14, "line": "“The script phrases sound fake when I say them.”", "tests": "Helps find authentic wording instead of insisting on the script"}], "good": ["Recognises speed and system skill.", "Helps Omar see the customer''s experience through questions.", "Agrees an authentic approach and a measurable check."], "red_flags": ["Insists on reading the script word for word", "No measurable follow-up"]}, "Ravi": {"archetype": "Strong performer settling into a new SME role", "public": {"headline": "Ravi became the team SME in W3 and is fielding most questions on the floor.", "observations": ["Ravi has 3 years on the program; QA 92%, CSAT 4.6.", "Since W3, Ravi has answered most floor questions, mainly from the new hires.", "Ravi''s own AHT rose to 475 s in W6, in line with the team.", "No time is scheduled for SME work in Ravi''s week."]}, "hidden": "Ravi is stretched: taking calls and answering questions without any SME time. Ravi also senses tension from a colleague who wanted the role.", "unlock": "A question about how the new role is going, or how they split their time.", "twists": [{"minute": 8, "line": "“I''m fine. I just need to work faster.”", "tests": "Probes beyond the reassurance"}, {"minute": 14, "line": "“Some people on the team aren''t happy I got the role.”", "tests": "Handles the team dynamic professionally, without gossip"}], "good": ["Recognises the contribution.", "Explores workload with open questions.", "Agrees practical support (SME time, a question queue) and a follow-up."], "red_flags": ["Assumes all is fine because the numbers are fine", "Discusses other team members'' feelings inappropriately"]}, "Ana": {"archetype": "Steady performer: recognition and development", "public": {"headline": "Ana meets every target and rarely needs support.", "observations": ["Ana has 2 years on the program; QA 90%, CSAT 4.5, attendance 98%.", "No QA fails this period.", "Ana has not asked for any development."]}, "hidden": "Ana is bored and quietly wondering about a move; would love to mentor new hires but hasn''t been asked.", "unlock": "A question about what they want from the next six months.", "twists": [{"minute": 8, "line": "“Is something wrong? My numbers are fine.”", "tests": "Explains the purpose of a development session"}, {"minute": 14, "line": "“I''d like to help train the new joiners, actually.”", "tests": "Turns the interest into a concrete development step"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Ana wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}, "Elena": {"archetype": "Experienced agent carrying the escalations", "public": {"headline": "Elena handles most of the team''s escalations.", "observations": ["Elena has 3 years on the program; QA 90%, CSAT 4.5.", "Elena took 11 escalated calls from colleagues in W5–W6.", "Elena''s AHT (482 s) is slightly above most tenured agents."]}, "hidden": "Elena takes escalations off others without being asked and is getting tired; nobody has noticed the extra load.", "unlock": "A question about how the escalations reach them, or how their week feels.", "twists": [{"minute": 8, "line": "“Someone has to take those calls.”", "tests": "Recognises the effort and explores the cost"}, {"minute": 14, "line": "“I''m honestly a bit worn out.”", "tests": "Responds with care and agrees how to share the load"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Elena wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}, "Grace": {"archetype": "Consistent performer with a quiet concern", "public": {"headline": "Grace is consistent across every metric.", "observations": ["Grace has 2 years on the program; QA 88%, CSAT 4.4, attendance 98%.", "No QA fails; no attendance issues."]}, "hidden": "Grace is thinking about asking for part-time hours for family reasons and is unsure how it will be received.", "unlock": "An open question about how things are going for them overall.", "twists": [{"minute": 8, "line": "“I''m not sure why we''re meeting.”", "tests": "Explains the purpose and builds trust"}, {"minute": 14, "line": "“I''ve been wondering about going part-time.”", "tests": "Listens and agrees a next step without promising outcomes"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Grace wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}, "Carla": {"archetype": "Energetic agent wanting to grow", "public": {"headline": "Carla''s CSAT is slightly below the team average.", "observations": ["Carla has a year on the team and volunteers for team activities; QA 88%, CSAT 4.3.", "In 1 of 3 monitored calls, Carla rushed the closing."]}, "hidden": "Carla wants to move into a training role and has been distracted planning team activities.", "unlock": "A question about their goals.", "twists": [{"minute": 8, "line": "“I thought my scores were OK.”", "tests": "Uses data without deflating"}, {"minute": 14, "line": "“I''d really like to be a trainer one day.”", "tests": "Links the goal to a performance step"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Carla wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}, "Dev": {"archetype": "Detail-oriented agent with long handling", "public": {"headline": "Dev has one of the longest AHT figures among tenured agents.", "observations": ["Dev has 2.5 years on the program; AHT 500 s, QA 87%.", "In 2 of 3 monitored calls, Dev re-read the full bill line by line to the customer."]}, "hidden": "After a complaint a year ago, Dev double-checks everything out loud to avoid mistakes.", "unlock": "A question about why they walk through the full bill.", "twists": [{"minute": 8, "line": "“I''d rather be slow than wrong.”", "tests": "Respects accuracy while exploring efficiency"}, {"minute": 14, "line": "“I got a complaint once and never want that again.”", "tests": "Responds with empathy and builds confidence"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Dev wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}, "Farid": {"archetype": "Ambitious agent wanting a quality role", "public": {"headline": "Farid has asked twice about joining the quality team.", "observations": ["Farid has a year on the team; QA 88%, CSAT 4.3.", "Farid keeps a personal log of their own QA feedback."]}, "hidden": "Farid wants clear feedback on what it takes to move into quality and feels overlooked.", "unlock": "A question about their career goals.", "twists": [{"minute": 8, "line": "“What do I need to do to get into QA?”", "tests": "Gives honest, specific guidance"}, {"minute": 14, "line": "“I feel like nobody takes me seriously.”", "tests": "Responds with recognition and a plan"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Farid wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}}, "cycle": {"conversation": ["Build rapport", "Listen, question, connect", "Agree on the root causes (RCAs)", "Build the action plan", "Start / Stop / Continue", "Gain commitment"], "funnel": ["Opening the conversation", "Probing further", "Finding the root cause", "Creating an action plan", "Offering help", "Gaining commitment", "Debrief and putting it all together"]}}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'team-coaching', 'B', 'Team 12 coaching (chat) · every agent is a scenario', false, '{"agents": {"Ali": {"archetype": "New joiner below bridge targets", "public": {"headline": "Ali is not yet meeting the bridge targets for new hires.", "observations": ["Ali has been on the production floor for 6 weeks (joined W1).", "Ali is polite and patient with customers; two customers thanked Ali by name in surveys this month.", "Ali''s Repeat contacts was 15.2% in W6 against a bridge target of 14%. QA is 83% (bridge target 80%).", "In the last four chats you monitored:", "a) In 2 of 4 chats, Ali put the customer on hold for more than two minutes while searching the knowledge base (KB).", "b) In 2 of 4 chats, the new refund-approval step bounced back and Ali restarted it from the beginning.", "c) In 1 chat, Ali skipped the closing summary; the customer came back the same day with the same question."]}, "hidden": "Ali was never shown the KB quick-reference during nesting and searches the full KB instead. Tenured agents have a workaround when the new refund-approval step bounced back; nobody showed Ali. Ali thinks this session means they are about to be let go.", "unlock": "An open question about what happens during the holds, or what feels hardest right now.", "twists": [{"minute": 8, "line": "“Bea and Chen are just as slow. Why am I the only one here?”", "tests": "Explains the purpose of the session with data, without comparing agents"}, {"minute": 14, "line": "“Honestly, I thought you called me in to let me go.”", "tests": "Builds trust and reframes the session as support"}], "good": ["Builds rapport first: Ali is new and nervous.", "Recognises what is working (soft skills, QA above bridge) before the gaps.", "Separates the team-wide rise since W4 from Ali''s own gaps (long KB holds, restarts).", "Agrees the root causes with Ali rather than announcing them.", "Plans to Ali''s learning style: shadowing Wei, a demo of the KB quick-reference.", "SMART plan with a follow-up date."], "red_flags": ["Tells Ali the solution in the first 5 minutes", "Treats the team-wide rise as Ali''s fault", "Ends without an agreed action or follow-up"]}, "Lina": {"archetype": "Tenured top performer slipping on CSAT and QA", "public": {"headline": "Lina has missed CSAT and QA targets for the last two weeks.", "observations": ["Lina has been on the program for 2 years and was the team''s top performer until W3.", "Lina''s QA fell from 94 in W3 to 86 in W6. The last two QA evaluations were 81% and 80% (target 82%).", "Lina missed 2 of the last 3 huddles and keeps the camera off in team meetings.", "In the last four chats you monitored:", "a) In 3 of 4 chats, Lina closed without asking if there was anything else or offering the retention offer.", "b) In 2 of 4 chats, Lina talked over the customer while they explained the problem.", "c) Lina still has the best Repeat contacts on the team (13.1%)."]}, "hidden": "Lina applied for the SME role in W3. Wei got it and nobody explained the decision. Lina feels unrecognised and has started looking at other jobs, and will only open up if they feel listened to.", "unlock": "An open question about how work feels lately, or what has changed since W3.", "twists": [{"minute": 8, "line": "“My numbers are still better than most of the team.”", "tests": "Acknowledges strengths and stays on the gap without arguing"}, {"minute": 14, "line": "“I applied for the SME role, you know. Nobody even told me why I didn''t get it.”", "tests": "Responds with empathy and addresses the career question alongside performance"}], "good": ["Opens with genuine rapport and recognition of the track record.", "Uses open and probing questions; lets Lina make the link between W3 and the drop.", "Treats the career disappointment as a root cause to address, not an excuse.", "Agrees a Start / Stop / Continue and a follow-up on the SME decision, with dates."], "red_flags": ["Lectures Lina on expectations without asking", "Ignores the career disappointment when it surfaces", "Speculates about Lina''s private life"]}, "Aisha": {"archetype": "Tenured agent not following process or using the KB", "public": {"headline": "Aisha received a QA red flag this week for not completing the new refund-approval step.", "observations": ["Aisha has been on the program for 4 years and new hires often go to Aisha for help.", "QA red-flagged 2 of Aisha''s chats in W6: the new refund-approval step was not completed (approval reason left blank).", "Aisha has not opened the KB or the team channel since W4 (team average: 18 KB views a week).", "Two customers came back after Aisha handled their requests with the old process.", "Aisha''s Repeat contacts (14.5%) and CSAT (4.4) are in line with the team."]}, "hidden": "Aisha was on leave in W4 and missed the briefing on the new refund-approval step. Aisha believes the KB is out of date, so stopped checking it, and will get defensive if lectured.", "unlock": "A question about how they found out about the new refund-approval step, or what they do when unsure of a process.", "twists": [{"minute": 8, "line": "“I''ve done this job for four years. I don''t need the KB.”", "tests": "Respects the experience while keeping the compliance risk on the table"}, {"minute": 14, "line": "“Wait, they changed it in W4? I was on leave that week.”", "tests": "Integrates new information: shifts from attitude to a missed update"}], "good": ["Acknowledges Aisha''s experience and value to new hires.", "Explains the impact of the missed step (security, compliance, repeat contacts) factually.", "Discovers the missed W4 briefing through questions rather than assuming attitude.", "Action plan fits Aisha''s style: a mock chat on the new step, a KB check for process changes, maybe helping brief others.", "SMART follow-up: e.g. next 10 chats fully compliant, QA re-check next week."], "red_flags": ["Threatens disciplinary action before exploring the cause", "Just tells Aisha to read the KB", "Leaves the compliance risk unaddressed"]}, "Tariq": {"archetype": "Attendance pattern after a shift change", "public": {"headline": "Tariq accounts for 4 of the team''s 12 Saturday absences since W2.", "observations": ["Tariq has been on the team for 1.5 years; chat quality is solid (QA 88%).", "Tariq was absent on 4 Saturdays since W2 and logged in late on two more. Attendance is 88% (team 96%).", "Tariq works the Saturday early shift (now starting at 06:00), which changed in W2.", "Tariq has not raised any concern with you."]}, "hidden": "Since the Saturday early shift (now starting at 06:00) changed in W2, there is no bus that works for Tariq; it leaves Tariq exhausted or late on Saturdays. Tariq is embarrassed to mention it.", "unlock": "A question about what changed around W2, or how they get to and from work on that shift.", "twists": [{"minute": 8, "line": "“I''m here every other day, aren''t I?”", "tests": "Stays factual about the pattern without accusing"}, {"minute": 14, "line": "“Since the shift moved, there''s no bus that gets me there and back.”", "tests": "Integrates new information and looks for a practical solution"}], "good": ["Opens with rapport and recognises Tariq''s chat quality.", "Presents the attendance pattern neutrally and asks before assuming.", "Links the pattern to the W2 shift change through Tariq''s own account.", "Agrees a practical plan (shift swap, transport option, escalate to workforce management) with a follow-up date."], "red_flags": ["Opens with a warning", "Ignores the transport issue once raised", "No follow-up agreed"]}, "Joy": {"archetype": "Attendance pattern with a personal cause", "public": {"headline": "Joy has missed 4 Saturdays since W2.", "observations": ["Joy has been on the team for a year and is well liked; QA 87%, CSAT 4.3.", "Joy was absent on 4 Saturdays since W2. Attendance is 89% (team 96%).", "Joy has always been reliable until W2."]}, "hidden": "Joy shared a car with a neighbour for the Saturday early shift (now starting at 06:00). When the shift changed in W2 the neighbour stopped working it, so Joy has no safe way to travel. Joy is worried about asking for special treatment.", "unlock": "A question about how they get to and from work, or what changed for them in W2.", "twists": [{"minute": 8, "line": "“Everyone has the odd day off. Why single me out?”", "tests": "Explains the pattern factually and with care"}, {"minute": 14, "line": "“My lift stopped when the shift changed. I didn''t want to make a fuss.”", "tests": "Responds with empathy and moves to a practical option"}], "good": ["Builds rapport and recognises Joy''s reliability before W2.", "Uses the data neutrally and asks open questions.", "Agrees a practical option and a follow-up."], "red_flags": ["Threatens escalation", "Ignores the reason once given"]}, "Bea": {"archetype": "New joiner with good quality but long handling", "public": {"headline": "Bea is above the bridge target on Repeat contacts.", "observations": ["Bea joined in W1 after working in retail; confident with customers.", "Bea''s Repeat contacts was 15.0% in W6 (bridge target 14%); QA 85% is above the bridge target.", "In 2 of 3 monitored chats, Bea spent several minutes on small talk before identifying the customer''s need.", "Bea offered a goodwill credit in one chat without checking eligibility."]}, "hidden": "Bea believes long friendly chats are what great service looks like, from retail. Nobody has explained the chat flow targets or the credit policy clearly.", "unlock": "A question about what great service means to them, or how they decide when to offer a credit.", "twists": [{"minute": 8, "line": "“Customers love chatting with me. Isn''t that the point?”", "tests": "Values the strength while linking it to the targets"}, {"minute": 14, "line": "“Nobody told me there were rules on credits.”", "tests": "Takes the new information as a knowledge gap, not misconduct"}], "good": ["Recognises the rapport strength.", "Helps Bea find a balance between warmth and efficiency.", "Clarifies the credit policy and agrees a measurable step with follow-up."], "red_flags": ["Tells Bea to stop chatting with customers", "Treats the credit as misconduct"]}, "Chen": {"archetype": "New joiner, quick with systems, light on empathy", "public": {"headline": "Chen is close to the bridge targets but customers rate the chats as cold.", "observations": ["Chen joined in W1 and studies IT part-time; quick with the systems.", "Chen''s Repeat contacts was 15.3% in W6 (bridge target 14%); QA 84%.", "In 2 of 3 monitored chats, Chen went straight to the fix without acknowledging the customer''s frustration.", "One survey comment: “Solved it, but felt like talking to a robot.”"]}, "hidden": "Chen thinks empathy statements waste the customer''s time and finds the scripted phrases fake.", "unlock": "A question about how they think the customer felt on a chat, or what they think of the empathy phrases.", "twists": [{"minute": 8, "line": "“I fixed their problem. Isn''t that what matters?”", "tests": "Links empathy to CSAT and resolution without lecturing"}, {"minute": 14, "line": "“The script phrases sound fake when I say them.”", "tests": "Helps find authentic wording instead of insisting on the script"}], "good": ["Recognises speed and system skill.", "Helps Chen see the customer''s experience through questions.", "Agrees an authentic approach and a measurable check."], "red_flags": ["Insists on reading the script word for word", "No measurable follow-up"]}, "Wei": {"archetype": "Strong performer settling into a new SME role", "public": {"headline": "Wei became the team SME in W3 and is fielding most questions on the floor.", "observations": ["Wei has 3 years on the program; QA 92%, CSAT 4.4.", "Since W3, Wei has answered most floor questions, mainly from the new hires.", "Wei''s own Repeat contacts rose to 13.6% in W6, in line with the team.", "No time is scheduled for SME work in Wei'