}, "Lucia": {"archetype": "Ambitious agent wanting a quality role", "public": {"headline": "Lucia has asked twice about joining the quality team.", "observations": ["Lucia has a year on the team; QA 89%, CSAT 4.3.", "Lucia keeps a personal log of their own QA feedback."]}, "hidden": "Lucia wants clear feedback on what it takes to move into quality and feels overlooked.", "unlock": "A question about their career goals.", "twists": [{"minute": 8, "line": "“What do I need to do to get into QA?”", "tests": "Gives honest, specific guidance"}, {"minute": 14, "line": "“I feel like nobody takes me seriously.”", "tests": "Responds with recognition and a plan"}], "good": ["Builds rapport and gives specific recognition with evidence.", "Uses open questions to find what Lucia wants next.", "Agrees a development goal with a measurable step and follow-up."], "red_flags": ["Only says “keep doing what you''re doing”", "No action or follow-up agreed"]}}, "cycle": {"conversation": ["Build rapport", "Listen, question, connect", "Agree on the root causes (RCAs)", "Build the action plan", "Start / Stop / Continue", "Gain commitment"], "funnel": ["Opening the conversation", "Probing further", "Finding the root cause", "Creating an action plan", "Offering help", "Gaining commitment", "Debrief and putting it all together"]}, "draft": "Version B (Team 12, chat) adapted from Version A. Review wording with COE before use."}'::jsonb);

-- The per-case Module 1 scenarios are retired; existing submissions keep pointing at them.
update public.scenarios set active = false where module = 1 and family in ('case-1', 'case-2', 'case-3', 'spare');

-- Module 1 submissions that haven't started move to the new scenario for their team version.
update public.module_submissions ms
   set scenario_id = sc.id
  from public.scenarios sc
 where ms.module = 1 and ms.status = 'assigned'
   and sc.module = 1 and sc.family = 'team-coaching' and sc.version = ms.dashboard_version;

-- Facilitator-visible part of the scenario: every agent's observations (never the role-play
-- brief), only for the owner and only once Module 1 has started.
create or replace function public.case_brief(p_submission uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case
    when sc.brief ? 'agents' then jsonb_build_object('agents',
      (select jsonb_object_agg(a.key, a.value -> 'public') from jsonb_each(sc.brief -> 'agents') a))
    else jsonb_build_object('agents', jsonb_build_object(sc.brief ->> 'agent', sc.brief -> 'public'))
  end
  from public.module_submissions ms
  join public.scenarios sc on sc.id = ms.scenario_id
  where ms.id = p_submission and ms.module = 1 and ms.started_at is not null
    and public.owns_submission(p_submission)
$$;

-- Module 1 no longer needs assigning: start_module picks the team scenario itself
-- (Team 7 for a first try, Team 12 for a reassessment) when none is set.
create or replace function public.start_module(p_submission uuid) returns public.module_submissions
language plpgsql security definer set search_path = '' as $$
declare
  s public.module_submissions;
  a public.attempts;
  v public.scenario_version;
begin
  if not public.owns_submission(p_submission) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into s from public.module_submissions where id = p_submission for update;
  select * into a from public.attempts where id = s.attempt_id;

  if a.consent_at is null then
    raise exception 'Recording consent is required before starting.';
  end if;
  if s.status <> 'assigned' then
    return s; -- idempotent
  end if;
  if s.module not in (1, 2) then
    raise exception 'Module 3 is run live by the certifier.';
  end if;
  if s.module = 1 and (s.scenario_id is null or not exists (
      select 1 from public.scenarios where id = s.scenario_id and family = 'team-coaching')) then
    v := case when s.try_no > 1 then 'B' else 'A' end;
    update public.module_submissions
       set scenario_id = (select id from public.scenarios where module = 1 and family = 'team-coaching' and version = v and active limit 1),
           dashboard_version = v
     where id = s.id returning * into s;
    if s.scenario_id is null then
      raise exception 'The Module 1 scenario is not set up yet.';
    end if;
  end if;
  if s.module = 2 then
    if s.scenario_id is null then
      raise exception 'No recording has been assigned yet.';
    end if;
    -- Gate: the latest Module 1 try in this attempt must be passed.
    if coalesce((
      select result from public.module_submissions
      where attempt_id = s.attempt_id and module = 1
      order by try_no desc limit 1
    ), 'not_passed') <> 'passed' then
      raise exception 'Module 2 unlocks after Module 1 is passed.';
    end if;
  end if;

  update public.module_submissions
     set status = 'in_progress',
         started_at = now(),
         phase = case when s.module = 1 then 'dashboard' else 'watching' end,
         phase_deadline = case when s.module = 1
           then now() + make_interval(secs => public.setting_int(array['timers', 'm1_dashboard_sec'], 900))
           else null end
   where id = s.id returning * into s;
  return s;
end $$;
